import {useIsAutodetectTimeZone} from '../../../hooks/useIsAutodetectTimeZone'
import type {ChangeId} from '../../../types'
import {displayDate} from '../../../utils/dateTimeUtils'
import {getChange} from '../../packages/Changes/Changes.selectors'
import {getCommiterName} from '../../packages/Changes/Changes.utils'

import {useAppSelector} from 'src/hooks/react-redux'

export const usePageTitle = (changeId: ChangeId): string | null => {
  const isAutodetectTimeZone = useIsAutodetectTimeZone()
  const changeExists = useAppSelector(state => getChange(state, changeId) != null)
  const date = useAppSelector(state => getChange(state, changeId)?.date)
  const commiterName = useAppSelector(state => getCommiterName(getChange(state, changeId)))

  const formatedDate = date != null ? displayDate(date, isAutodetectTimeZone, true) : null

  if (!changeExists) {
    return null
  }

  return `${commiterName} change${formatedDate != null ? ` on ${formatedDate}` : null}`
}
