import {HTTPError, HTTPCodesEnum} from '@jetbrains/teamcity-ui/dist/services'
import {memo, useCallback} from 'react'
import {useLocation, useNavigate} from 'react-router'

import {useBooleanQueryParam, getChangeId, useQueryParam} from '../../../hooks/routes'
import useDocumentTitle from '../../../hooks/useDocumentTitle'
import {getChangesArg} from '../../../rest/arguments'
import {getHrefWithQueryParams} from '../../../routes'
import {restApi} from '../../../services/rest'
import type {ChangeId} from '../../../types'
import {stringifyId, toBuildTypeId} from '../../../types'
import {isValue} from '../../../utils/guards'
import Loader from '../../common/Loader/Loader'
import {ChangeBuildsContext} from '../../packages/Changes/ChangeDetailsTabs/ChangeBuilds/ChangeBuilds.context'
import ChangeDetailsTabs from '../../packages/Changes/ChangeDetailsTabs/ChangeDetailsTabs'
import {ChangePageTabName} from '../../packages/Changes/ChangeDetailsTabs/ChangeDetailsTabs.types'
import {getChange} from '../../packages/Changes/Changes.selectors'

import {usePageTitle} from './ChangePage.hooks'
import ChangePageHeader from './ChangePageHeader'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = {
  changeId: ChangeId
}

const context = {withInfiniteScroll: true, pageSize: 50}

function ChangePage({changeId}: Props) {
  const navigate = useNavigate()
  const location = useLocation()
  const pageTitle = usePageTitle(changeId)

  const personal = useBooleanQueryParam('personal')
  const buildTypeIdString = useQueryParam('buildTypeId')
  const buildTypeId = buildTypeIdString != null ? toBuildTypeId(buildTypeIdString) : null
  const currentTabString = useQueryParam('tab')
  const currentTab = isValue(ChangePageTabName, currentTabString)
    ? currentTabString
    : ChangePageTabName.FILES

  const locator = `id:${stringifyId(changeId)},personal:${personal}`
  const {isLoading} = restApi.endpoints.getAllChanges.useQuery(getChangesArg(locator), {
    selectFromResult: ({isLoading}) => ({isLoading}),
  })
  const changeExists = useAppSelector(state => getChange(state, changeId) != null)

  const getTabLink = useCallback(
    (tabId: string) =>
      getHrefWithQueryParams(location, null, params => ({...params, tab: stringifyId(tabId)})),
    [location],
  )
  const onSelectTab = useCallback(
    (tabId: string) => navigate(getTabLink(tabId), {preventScrollReset: true}),
    [navigate, getTabLink],
  )

  useDocumentTitle(
    isLoading
      ? 'TeamCity Loading...'
      : `Change page${pageTitle != null ? `: ${pageTitle}` : ''} — TeamCity`,
  )

  if (isLoading) {
    return <Loader />
  }

  if (!window.GLOBAL_ERROR_PAGE_DISABLED && changeId != null && !changeExists) {
    const message = `Change with\u00a0id '${stringifyId(changeId)}' does\u00a0not\u00a0exist`
    throw new HTTPError(message, HTTPCodesEnum.NOT_FOUND)
  }

  return (
    <>
      <ChangePageHeader changeId={changeId} />
      <ChangeBuildsContext.Provider value={context}>
        <ChangeDetailsTabs
          changeId={changeId}
          buildTypeId={buildTypeId}
          currentTab={currentTab}
          onSelectTab={onSelectTab}
          withHref
        />
      </ChangeBuildsContext.Provider>
    </>
  )
}

function ChangePageWrapper() {
  const location = useLocation()
  const changeId = getChangeId(location.pathname)
  return changeId != null ? <ChangePage changeId={changeId} /> : null
}

export default memo(ChangePageWrapper)
